#!/usr/bin/env python3
"""チャート画面の「企業と財務」用のデータを作る。

Yahoo Finance(yfinance)の年次と四半期の損益計算書・貸借対照表・キャッシュフロー計算書から、
売上と成長率、コスト構造(対売上比率)、財務レバレッジ(純有利子負債/EBITDA)、フリーキャッシュフロー、
EPS成長率の分解(売上成長・利益率の変化・株数の変化)、直近四半期の前年同期比を作る。
Yahooは四半期を直近5〜6期しか返さないので、米国企業は SEC EDGAR(XBRL の companyfacts)から四半期を最大 QKEEP 期(4年)とって合わせる。\nSECは新しい決算が出た銘柄だけ取り直す。外国企業など SEC に四半期がない銘柄は、Yahoo の分を毎週ためていく。
決算は四半期ごとにしか変わらないので、銘柄ごとに fund_cache.json に取得日を持ち、TTL_DAYS より新しければ取り直さない。

対象: ダッシュボードに載る銘柄(ウォッチリスト・階層ビューの個別銘柄)と、売買代金(直近20日平均)の上位 TOP 銘柄。
表示用で、判定には使わない。

出力(out/search/ 以下):
  fund_<k>.json  k = ティッカーの文字コードの合計を10で割った余り(ページ側も同じ計算で探す)

使い方:
  python make_fundamentals.py --out output [--threads 4] [--top 1000]
"""
from __future__ import annotations

import argparse
import datetime as dt
import gzip
import json
import math
import sys
import time
import urllib.error
import urllib.request
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

import pandas as pd
import yfinance as yf

HERE = Path(__file__).resolve().parent
CHUNKS = 10
TTL_DAYS = 7
QKEEP = 16  # 四半期は最大16期(4年)までためる


def chunk_of(t: str) -> str:
    return str(sum(ord(ch) for ch in t) % CHUNKS)


def num(v, nd=0):
    try:
        v = float(v)
    except (TypeError, ValueError):
        return None
    if math.isnan(v) or math.isinf(v):
        return None
    return round(v, nd) if nd else round(v)


def row(df: pd.DataFrame, names: list[str], cols) -> list:
    for n in names:
        if n in df.index:
            return [num(df.at[n, c], 4 if "EPS" in n else 0) for c in cols]
    return [None] * len(cols)


def stmt(inc: pd.DataFrame, bal, cf, need_rev: bool = True) -> dict | None:
    """損益・貸借・CFの表から、売上のある期だけを古い順に並べた dict を作る(年次・四半期共通)。"""
    if inc is None or inc.empty or "Total Revenue" not in inc.index:
        return None
    cols = [c for c in sorted(inc.columns) if pd.notna(inc.at["Total Revenue", c])]
    if not cols:
        return None
    y = {
        "fy": [c.strftime("%y/%m") for c in cols],
        "rev": row(inc, ["Total Revenue", "Operating Revenue"], cols),
        "cogs": row(inc, ["Cost Of Revenue", "Reconciled Cost Of Revenue"], cols),
        "gp": row(inc, ["Gross Profit"], cols),
        "rd": row(inc, ["Research And Development"], cols),
        "op": row(inc, ["Operating Income", "Total Operating Income As Reported"], cols),
        "ni": row(inc, ["Net Income Common Stockholders", "Net Income"], cols),
        "eps": row(inc, ["Diluted EPS", "Basic EPS"], cols),
        "sh": row(inc, ["Diluted Average Shares", "Basic Average Shares"], cols),
        "ebitda": row(inc, ["EBITDA", "Normalized EBITDA"], cols),
    }
    ok_bal = bal is not None and not bal.empty
    y["debt"] = [num(bal.at["Total Debt", c]) if ok_bal and "Total Debt" in bal.index and c in bal.columns else None for c in cols]
    cashk = next((k for k in ["Cash Cash Equivalents And Short Term Investments", "Cash And Cash Equivalents"] if ok_bal and k in bal.index), None)
    y["cash"] = [num(bal.at[cashk, c]) if cashk and c in bal.columns else None for c in cols]
    ok_cf = cf is not None and not cf.empty
    for key, names in [("ocf", ["Operating Cash Flow", "Cash Flow From Continuing Operating Activities"]), ("capex", ["Capital Expenditure"]),
                       ("fcf", ["Free Cash Flow"]), ("buyback", ["Repurchase Of Capital Stock", "Common Stock Payments"]), ("div", ["Cash Dividends Paid"])]:
        n = next((n for n in names if ok_cf and n in cf.index), None)
        y[key] = [num(cf.at[n, c]) if n and c in cf.columns else None for c in cols]
    return y


def merge_periods(old: dict | None, new: dict | None, keep: int) -> dict | None:
    """前回までに取った期と今回取った期を合わせる(Yahooは四半期を直近5〜6期しか返さないので、毎週ためていく)。"""
    if not old:
        return new
    if not new:
        return old
    keys = [k for k in new if k != "fy"]
    by = {}
    for src in (old, new):  # 同じ期は新しい方で上書き
        for i, lab in enumerate(src.get("fy", [])):
            cur = by.setdefault(lab, {})
            for k in keys:
                v = (src.get(k) or [None] * len(src["fy"]))[i] if i < len(src.get(k) or []) else None
                if v is not None or k not in cur:
                    cur[k] = v
    labs = sorted(by)[-keep:]
    return {"fy": labs, **{k: [by[l].get(k) for l in labs] for k in keys}}


def fetch(t: str):
    for a in range(3):
        try:
            T = yf.Ticker(t)
            y = stmt(T.income_stmt, T.balance_sheet, T.cashflow)
            if y is None:
                if a < 2:  # Yahooが一時的に空を返すことがあるので、待って取り直す
                    time.sleep(3 * (a + 1))
                    continue
                return t, {"none": True}
            q = T.quarterly_income_stmt
            # 四半期の財務3表(年次と同じ形で "qt" に入れる)
            y["qt"] = stmt(q, T.quarterly_balance_sheet, T.quarterly_cashflow)
            # 直近四半期(前年同期比)と直近4四半期(TTM)の EPS
            if q is not None and not q.empty:
                qc = sorted(q.columns)
                def qv(n):
                    return {c: num(q.at[n, c], 4 if "EPS" in n else 0) for c in qc} if n in q.index else {}
                qr, qe = qv("Total Revenue"), qv("Diluted EPS") or qv("Basic EPS")
                def yoy(d):
                    have = [c for c in qc if d.get(c) is not None]
                    if not have:
                        return None, None, None
                    lc = have[-1]
                    prev = [c for c in have if 330 <= (lc - c).days <= 400]
                    return lc, d[lc], (d[prev[0]] if prev else None)
                rc, rv, rp = yoy(qr)
                ec, ev, ep = yoy(qe)
                if rc is not None or ec is not None:
                    y["q"] = {"rev_end": rc.strftime("%y/%m/%d") if rc is not None else None, "rev": rv, "rev_prev": rp,
                              "eps_end": ec.strftime("%y/%m/%d") if ec is not None else None, "eps": ev, "eps_prev": ep}
                    l4 = [qe.get(c) for c in qc[-4:]]
                    if len(l4) == 4 and all(v is not None for v in l4):
                        y["q"]["eps_ttm"] = round(sum(l4), 4)
            return t, y
        except Exception as e:  # 一時的な失敗は待って再試行
            if "Too Many" in str(e) or "401" in str(e):
                time.sleep(10 * (a + 1))
            else:
                time.sleep(2 * (a + 1))
    return t, None


# ---- SEC EDGAR(XBRL)から四半期を最大16期とる ----
SEC_UA = {"User-Agent": "stage-checker/1.0 (personal research tool)", "Accept-Encoding": "gzip, deflate"}
SEC_TICKERS = "https://www.sec.gov/include/ticker.txt"
SEC_FACTS = "https://data.sec.gov/api/xbrl/companyfacts/CIK{:010d}.json"
SEC_DUR = {  # 期間の値(損益・CF)。先にあるものを優先
    "rev": ["Revenues", "RevenueFromContractWithCustomerExcludingAssessedTax", "RevenueFromContractWithCustomerIncludingAssessedTax", "SalesRevenueNet", "RevenuesNetOfInterestExpense"],
    "cogs": ["CostOfRevenue", "CostOfGoodsAndServicesSold", "CostOfGoodsSold", "CostOfGoodsAndServiceExcludingDepreciationDepletionAndAmortization"],
    "gp": ["GrossProfit"],
    "rd": ["ResearchAndDevelopmentExpense", "ResearchAndDevelopmentExpenseExcludingAcquiredInProcessCost"],
    "op": ["OperatingIncomeLoss"],
    "ni": ["NetIncomeLossAvailableToCommonStockholdersBasic", "NetIncomeLoss"],
    "eps": ["EarningsPerShareDiluted", "EarningsPerShareBasic"],
    "sh": ["WeightedAverageNumberOfDilutedSharesOutstanding", "WeightedAverageNumberOfSharesOutstandingBasic"],
    "da": ["DepreciationDepletionAndAmortization", "DepreciationAndAmortization", "DepreciationAmortizationAndAccretionNet", "Depreciation"],
    "ocf": ["NetCashProvidedByUsedInOperatingActivities", "NetCashProvidedByUsedInOperatingActivitiesContinuingOperations"],
    "capex": ["PaymentsToAcquirePropertyPlantAndEquipment", "PaymentsToAcquireProductiveAssets"],
    "buyback": ["PaymentsForRepurchaseOfCommonStock"],
    "div": ["PaymentsOfDividendsCommonStock", "PaymentsOfDividends"],
}
SEC_INST = {  # 期末の値(貸借)。組み合わせ=[部品, ...]で部品を合計する。部品は項目名の候補(前にあるものを優先し、ない期を後ろで埋める)
    "cash": [[["CashCashEquivalentsAndShortTermInvestments"]],
             [["CashAndCashEquivalentsAtCarryingValue", "CashCashEquivalentsRestrictedCashAndRestrictedCashEquivalents"],
              ["ShortTermInvestments", "MarketableSecuritiesCurrent", "AvailableForSaleSecuritiesDebtSecuritiesCurrent", "AvailableForSaleSecuritiesDebtSecurities"]]],
    # 有利子負債はYahooの Total Debt に合わせてリース負債も含める
    "debt": [[["LongTermDebt"], ["ShortTermBorrowings", "CommercialPaper"], ["OperatingLeaseLiability"], ["FinanceLeaseLiability"]],
             [["LongTermDebtNoncurrent"], ["LongTermDebtCurrent", "DebtCurrent"], ["ShortTermBorrowings", "CommercialPaper"], ["OperatingLeaseLiability"], ["FinanceLeaseLiability"]]],
}


def qlabel(end: str) -> str:
    """決算期末を年/月の見出しにする(土曜締めなどで月初の数日にずれる会社は前の月に寄せる。Yahooの表記に合わせる)。"""
    d = dt.date.fromisoformat(end) - dt.timedelta(days=7)
    return d.strftime("%y/%m")


def sec_cik_map(out: Path) -> dict[str, int]:
    p = out / "sec_ticker.txt"
    if not p.exists() or time.time() - p.stat().st_mtime > 30 * 86400:
        try:
            req = urllib.request.Request(SEC_TICKERS, headers=SEC_UA)
            with urllib.request.urlopen(req, timeout=30) as r:
                body = r.read()
            if r.headers.get("Content-Encoding") == "gzip":
                body = gzip.decompress(body)
            if body.count(b"\t") > 5000:
                p.write_bytes(body)
        except Exception as e:  # 取れなければ前回の表を使う
            print(f"SECの銘柄表を更新できませんでした: {e}", file=sys.stderr)
    m = {a.upper(): int(b) for a, b in (l.split("\t") for l in p.read_text().split("\n") if "\t" in l)} if p.exists() else {}
    ov = HERE / "sec_cik_overrides.tsv"  # 銘柄表が古くて見つからない銘柄を手で足す
    if ov.exists():
        m.update({a.upper(): int(b) for a, b in (l.split("\t") for l in ov.read_text(encoding="utf-8").split("\n") if "\t" in l and not l.startswith("#"))})
    return m


def _quarters_dur(items: list) -> dict[str, float]:
    """期間の値から3か月分の値を作る。10-QのCFは年初からの累計なので、差し引きで3か月分にする。Q4は通期−9か月。"""
    by = {}
    for x in items:
        if "start" not in x:
            continue
        k = (x["start"], x["end"])
        if k not in by or x.get("filed", "") > by[k].get("filed", ""):
            by[k] = x
    days = lambda a, b: (dt.date.fromisoformat(b) - dt.date.fromisoformat(a)).days
    q = {}
    for (s, e), x in by.items():
        if 80 <= days(s, e) <= 100:
            q[e] = x["val"]
    for (s, e), x in by.items():
        L = days(s, e)
        if L <= 100 or e in q:
            continue
        prev = [(e2, y) for (s2, e2), y in by.items() if s2 == s and 80 <= days(e2, e) <= 100]
        if prev:
            q[e] = x["val"] - prev[0][1]["val"]
    return q


def _instant(items: list) -> dict[str, float]:
    by = {}
    for x in items:
        if "start" in x:
            continue
        if x["end"] not in by or x.get("filed", "") > by[x["end"]].get("filed", ""):
            by[x["end"]] = x
    return {e: x["val"] for e, x in by.items()}


def sec_quarters(cik: int) -> dict | None:
    for a in range(3):
        try:
            req = urllib.request.Request(SEC_FACTS.format(cik), headers=SEC_UA)
            with urllib.request.urlopen(req, timeout=60) as r:
                body = r.read()
                if r.headers.get("Content-Encoding") == "gzip":
                    body = gzip.decompress(body)
            g = json.loads(body).get("facts", {}).get("us-gaap", {})
            break
        except urllib.error.HTTPError as e:
            if e.code == 404:
                return None
            time.sleep(5 * (a + 1))
        except Exception:
            time.sleep(5 * (a + 1))
    else:
        return None
    if not g:
        return None

    def units(c):
        u = g.get(c, {}).get("units", {})
        return next(iter(u.values()), [])
    near = lambda d, e: d.get(e) if e in d else next((v for k, v in d.items() if abs((dt.date.fromisoformat(k) - dt.date.fromisoformat(e)).days) <= 6), None)
    vals: dict[str, dict] = {}
    for key, names in SEC_DUR.items():  # 会社が途中で使う項目名を変えることがあるので、優先順に埋めていく
        d: dict[str, float] = {}
        for c in names:
            if key in ("eps", "sh"):  # 1株あたり・株数は足し引きできないので、3か月の値だけ使う
                q = {}
                for x in units(c):
                    if "start" in x and 80 <= (dt.date.fromisoformat(x["end"]) - dt.date.fromisoformat(x["start"])).days <= 100:
                        if x["end"] not in q or x.get("filed", "") > q[x["end"]][1]:
                            q[x["end"]] = (x["val"], x.get("filed", ""))
                q = {e: v for e, (v, _) in q.items()}
            else:
                q = _quarters_dur(units(c))
            for e, v in q.items():
                if near(d, e) is None:
                    d[e] = v
        if d:
            vals[key] = d
    if "rev" not in vals or max(vals["rev"]) < str(dt.date.today().year - 1):
        # 銀行は売上の項目がないので、Yahooと同じく 純金利収入+非金利収入 を売上とみなす
        nii = _quarters_dur(units("InterestIncomeExpenseNet")) or _quarters_dur(units("InterestIncomeExpenseAfterProvisionForLoanLoss"))
        non = _quarters_dur(units("NoninterestIncome"))
        if nii and non:
            vals["rev"] = {e: v + (near(non, e) or 0) for e, v in nii.items()}
    if "rev" not in vals:
        return None
    ends = sorted(vals["rev"])[-QKEEP:]
    for key, combos in SEC_INST.items():  # 対象の期をいちばん多く埋められる組み合わせ(同じなら直近の値が大きい方=含む範囲が広い方)を使う
        best, score = None, (0, 0)
        for combo in combos:
            parts = []
            for names in combo:
                d0: dict[str, float] = {}
                for c in names:
                    for e, v in _instant(units(c)).items():
                        if near(d0, e) is None:
                            d0[e] = v
                parts.append(d0)
            if not parts[0]:
                continue
            def part_at(names, p, e):
                v = near(p, e)
                if v is None and any("Lease" in n for n in names):  # リース負債は年1回しか開示しない会社が多いので、1年以内の直前の値を使う
                    prev = [k for k in p if k <= e and (dt.date.fromisoformat(e) - dt.date.fromisoformat(k)).days <= 370]
                    v = p[max(prev)] if prev else None
                return v or 0
            d = {e: v + sum(part_at(names, p, e) for names, p in zip(combo[1:], parts[1:])) for e, v in parts[0].items()}
            sc = (sum(near(d, e) is not None for e in ends), near(d, ends[-1]) or 0)
            if sc > score:
                best, score = d, sc
        if best:
            vals[key] = best
    labs = [qlabel(e) for e in ends]
    y = {"fy": labs}
    for key in ["rev", "cogs", "gp", "rd", "op", "ni", "eps", "sh", "da", "ocf", "capex", "buyback", "div", "cash", "debt"]:
        d = vals.get(key, {})
        y[key] = [near(d, e) if d else None for e in ends]
    # 株式分割: 株数が前の期から1.5倍超・2/3未満に飛んだら分割とみなし、古い期を今の株数ベースにそろえる
    sh, f = y["sh"], 1.0
    nxt = None
    for i in range(len(sh) - 1, -1, -1):
        if sh[i] is None or sh[i] <= 0:
            sh[i] = None
            continue
        if nxt is not None:
            r = nxt / sh[i]
            if r > 1.5:
                f *= round(r)
            elif r < 2 / 3:
                f /= round(1 / r)
        nxt = sh[i]
        sh[i] = sh[i] * f
    for i in range(len(sh)):  # 第4四半期は株数の開示がないので前後の期の平均
        if sh[i] is None:
            nb = [sh[k] for k in (i - 1, i + 1) if 0 <= k < len(sh) and sh[k]]
            sh[i] = sum(nb) / len(nb) if nb else None
    # EPSは 純利益÷株数 でそろえる(分割前の古い開示値が混じらないように)
    y["eps"] = [round(n / s_, 4) if n is not None and s_ else None for n, s_ in zip(y["ni"], sh)]
    y["sh"] = [num(v) for v in sh]
    for key in ["rev", "cogs", "gp", "rd", "op", "ni", "da", "ocf", "capex", "buyback", "div", "cash", "debt"]:
        y[key] = [num(v) for v in y[key]]
    # 合わせ方をYahooにそろえる: 設備投資・自社株買い・配当は支出なのでマイナス、FCF=営業CF−設備投資、EBITDA=営業利益+減価償却
    for k in ["capex", "buyback", "div"]:
        y[k] = [-abs(v) if v is not None else None for v in y[k]]
    y["fcf"] = [o + c if o is not None and c is not None else None for o, c in zip(y["ocf"], y["capex"])]
    y["ebitda"] = [o + d if o is not None and d is not None else None for o, d in zip(y["op"], y.pop("da"))]
    y["gp"] = [g_ if g_ is not None else (r - c if r is not None and c is not None else None) for g_, r, c in zip(y["gp"], y["rev"], y["cogs"])]
    return y


def sec_matches(sec: dict, yq: dict | None) -> bool:
    """ティッカーの付け替えで別会社を引いていないか、Yahooの四半期売上と照らし合わせる。"""
    if not yq:
        return True
    a = dict(zip(sec["fy"], sec["rev"]))
    pairs = [(a[l], v) for l, v in zip(yq.get("fy", []), yq.get("rev", [])) if a.get(l) and v]
    if not pairs:
        return False
    return sum(abs(s / v - 1) < 0.05 for s, v in pairs) >= max(1, len(pairs) // 2)



def targets(out: Path, top: int) -> list[str]:
    d = json.loads((out / "dashboard_data.json").read_text(encoding="utf-8"))
    ts = [r["ticker"] for r in d.get("watchlist", [])] + [r["ticker"] for r in d.get("stocks", [])]
    dv = []
    for k in range(10):
        p = out / "search" / f"search_px_{k}.json"
        if p.exists():
            for r in json.loads(p.read_text(encoding="utf-8"))["rows"]:
                x = [a * b * 100 for a, b in zip(r["c"][-20:], r["v"][-20:]) if a is not None and b is not None]
                if x:
                    dv.append((sum(x) / len(x), r["t"]))
    ts += [t for _, t in sorted(dv, reverse=True)[:top]]
    return list(dict.fromkeys(ts))


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", default="output")
    ap.add_argument("--threads", type=int, default=4)
    ap.add_argument("--top", type=int, default=1000)
    ap.add_argument("--force", action="store_true", help="キャッシュの日付にかかわらず全部取り直す")
    args = ap.parse_args()
    out = Path(args.out)
    so = out / "search"
    cache_p = out / "fund_cache.json"
    cache = json.loads(cache_p.read_text(encoding="utf-8")) if cache_p.exists() else {}
    today = dt.date.today()
    want = targets(out, args.top)
    stale = [t for t in want if args.force or t not in cache or (today - dt.date.fromisoformat(cache[t].get("fetched", "2000-01-01"))).days >= TTL_DAYS]
    print(f"対象 {len(want)} 銘柄、取り直し {len(stale)}", flush=True)
    ok = fail = 0
    with ThreadPoolExecutor(args.threads) as ex:
        for i, (t, y) in enumerate(ex.map(fetch, stale), 1):
            if y is None:
                fail += 1
                continue
            old = cache.get(t) or {}
            if y.get("none") and not old.get("none") and old.get("fy"):
                fail += 1  # 一時的に空で返ってきたときは前回のデータを残す
                continue
            ok += 1
            y["fetched"] = today.isoformat()
            if not y.get("none"):
                y["qt"] = merge_periods((cache.get(t) or {}).get("qt"), y.get("qt"), QKEEP)
            cache[t] = y
            if i % 100 == 0:
                print(f"{i}/{len(stale)}", flush=True)
                cache_p.write_text(json.dumps(cache, ensure_ascii=False), encoding="utf-8")
    cache_p.write_text(json.dumps(cache, ensure_ascii=False), encoding="utf-8")

    # SECの四半期(最大16期)。Yahooの最新四半期がSEC側より新しい銘柄(=新しい決算が出た銘柄)と、まだ取っていない銘柄だけ取る
    cik = sec_cik_map(out)
    need = []
    for t in want:
        y = cache.get(t) or {}
        if y.get("none") or t.upper() not in cik:
            continue
        sec = y.get("sec") or {}
        ylast = ((y.get("qt") or {}).get("fy") or [""])[-1]
        if not sec or (sec.get("fy") and ylast > sec["fy"][-1] and (today - dt.date.fromisoformat(sec.get("fetched", "2000-01-01"))).days >= 3) \
                or (not sec.get("fy") and (today - dt.date.fromisoformat(sec.get("fetched", "2000-01-01"))).days >= 30):
            need.append(t)
    print(f"SEC 対象 {len(need)} 銘柄", flush=True)
    sok = 0
    def sec_one(t):
        time.sleep(0.25)  # SECの上限(毎秒10回)より十分ゆっくり
        return t, sec_quarters(cik[t.upper()])
    with ThreadPoolExecutor(2) as ex:
        for i, (t, sq) in enumerate(ex.map(sec_one, need), 1):
            if sq and not sec_matches(sq, cache[t].get("qt")):
                sq = None
            cache[t]["sec"] = {**(sq or {}), "fetched": today.isoformat()}
            sok += bool(sq)
            if i % 100 == 0:
                print(f"SEC {i}/{len(need)}", flush=True)
                cache_p.write_text(json.dumps(cache, ensure_ascii=False), encoding="utf-8")
    cache_p.write_text(json.dumps(cache, ensure_ascii=False), encoding="utf-8")
    print(f"SEC 取得 {sok}/{len(need)}", flush=True)

    # 社名・業種・時価総額・事業概要は profile_cache.json(なければ取って足す)と検索一覧から足す
    sys.path.insert(0, str(HERE))
    import make_dashboard_data as mdd
    mdd.fetch_profiles(want, out / "profile_cache.json", today.isoformat())
    prof = json.loads((out / "profile_cache.json").read_text(encoding="utf-8")) if (out / "profile_cache.json").exists() else {}
    idx = {r["t"]: r for r in json.loads((so / "search_index.json").read_text(encoding="utf-8"))["rows"]}
    import rs_watchlist as rw
    import theme_etfs as te
    hp = out / "etf_holdings.json"  # make_etf_holdings.py の出力(SECの保有明細)
    hold = json.loads(hp.read_text(encoding="utf-8")).get("by_ticker", {}) if hp.exists() else {}
    groups: dict[str, list] = {str(k): [] for k in range(CHUNKS)}
    for t, y in cache.items():
        if y.get("none"):
            continue
        p = prof.get(t, {})
        r = {"t": t, **{k: v for k, v in y.items() if k not in ("fetched", "sec")}, "asof": y.get("fetched")}
        sec = {k: v for k, v in (y.get("sec") or {}).items() if k != "fetched"}
        if sec.get("fy"):  # SECの四半期を土台に、Yahooの分(直近)で足りないところを埋める
            r["qt"] = merge_periods(r.get("qt"), sec, QKEEP)
            r["qsrc"] = "SEC+Yahoo"
        r["name"] = p.get("name") or (idx.get(t) or {}).get("n") or t
        r["industry"] = p.get("industry") or ""
        r["mcap"] = num(p.get("market_cap"))
        r["summary"] = (p.get("summary") or "")[:700]
        r["emp"] = num(p.get("employees"))
        ind = r["industry"]
        r["ind_ja"] = te.INDUSTRY_JA.get(ind, ind)
        r["sector"] = (idx.get(t) or {}).get("sec") or rw.YAHOO_TO_GICS.get(p.get("sector_yahoo") or "", "")
        r["sector_etf"] = rw.SECTOR_ETF.get(r["sector"], "")
        if hold:  # 実際に組み入れているテーマETF(比率の大きい順、最大5本)。取れていなければ業種からの推測
            hs = hold.get(t, [])[:5]
            r["themes"], r["theme_w"], r["theme_src"] = [e for e, _ in hs], [w for _, w in hs], "holdings"
        else:
            r["themes"] = te.INDUSTRY_THEMES.get(ind, [])
        groups[chunk_of(t)].append(r)
    meta = [{"label": "make_fundamentals.py", "value": Path(__file__).read_text(encoding="utf-8"), "type": "code", "lang": "python"},
            {"label": "Input", "value": "Yahoo Finance(年次・四半期の財務3表)、SEC EDGAR(四半期、XBRL)、profile_cache.json"}]
    for k, rows in groups.items():
        (so / f"fund_{k}.json").write_text(json.dumps({"rows": rows, "meta": meta}, ensure_ascii=False, separators=(",", ":")), encoding="utf-8")
    sizes = [(so / f"fund_{k}.json").stat().st_size for k in groups]
    print(f"取得 {ok}、失敗 {fail}、掲載 {sum(len(v) for v in groups.values())} 銘柄、最大 {max(sizes) / 1e6:.2f}MB")


